from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel
import stripe

router = APIRouter(prefix="/merchants")

class OnboardingLinkResponse(BaseModel):
    account_id: str
    onboarding_url: str

@router.post("/{account_id}/onboarding-link", response_model=OnboardingLinkResponse)
async def generate_merchant_onboarding_link(
    account_id: str,
    merchant_repo: MerchantRepository = Depends(get_merchant_repo),
    user: User = Depends(get_current_user)
):
    merchant = await merchant_repo.get_by_stripe_account_id(account_id)
    if not merchant:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Merchant account not found")

    if merchant.owner_user_id != user.id and not user.is_platform_admin:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Access denied to requested Stripe Connect account")

    try:
        account_link = stripe.AccountLink.create(
            account=account_id,
            refresh_url="https://platform.com/reauth",
            return_url="https://platform.com/dashboard",
            type="account_onboarding"
        )
        return OnboardingLinkResponse(account_id=account_id, onboarding_url=account_link.url)
    except stripe.error.StripeError as err:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(err))
